<?php
require __DIR__.'/bootstrap.php';$store=new AniSms\Infrastructure\Database($wpdb);$store->migrate();add_filter('pre_wp_mail','__return_true');$home=get_option('home');update_option('home','https://example.test');update_option('ani_sms_modules',array('auth','stock'));update_option('ani_sms_stock_settings',array('template'=>123,'mapping'=>array('Product'=>'product_name','Link'=>'product_url')));
$calls=0;add_filter('pre_http_request',function($pre,$args,$url)use(&$calls){++$calls;ani_check('https://api.sms.ir/v1/send/verify/'===$url,'stock uses transactional verify endpoint');$data=json_decode($args['body'],true);ani_check(123===$data['templateId']&&2===count($data['parameters']),'stock sends exact approved mapping');return array('response'=>array('code'=>200),'body'=>'{"status":1,"data":{"messageId":765432}}','headers'=>array());},1,3);
$user=wp_insert_user(array('user_login'=>'ani_stock_boundary_'.bin2hex(random_bytes(5)),'user_pass'=>wp_generate_password(30),'role'=>'subscriber'));$phone='+989127771111';$store->query($wpdb->prepare("DELETE FROM {$store->table('identities')} WHERE phone=%s",$phone));$store->insert('identities',array('phone'=>$phone,'user_id'=>$user,'verified_at'=>time(),'verification_mode'=>'local'));
$p=new WC_Product_Simple();$p->set_name('Live transport fixture');$p->set_status('publish');$p->set_regular_price('1000');$p->set_stock_status('outofstock');$p->save();
$queue=new AniSms\Infrastructure\Queue($store);$service=new AniSms\Stock\Service($store,$queue);(new AniSms\Stock\Module($store,$queue))->boot();ani_rejects(fn()=>$service->request($p->get_id(),$user,true),'local proof cannot grant live stock request');
$store->query($wpdb->prepare("UPDATE {$store->table('identities')} SET verification_mode='unknown' WHERE user_id=%d",$user));ani_rejects(fn()=>$service->request($p->get_id(),$user,true),'unknown proof rejected');$store->query($wpdb->prepare("UPDATE {$store->table('identities')} SET verification_mode='live' WHERE user_id=%d",$user));
$id=$service->request($p->get_id(),$user,true);ani_check('live'===$wpdb->get_var($wpdb->prepare("SELECT mode FROM {$store->table('stock_requests')} WHERE id=%d",$id)),'live request mode stored');$p->set_stock_status('instock');$p->save();$store->query("UPDATE {$store->table('jobs')} SET available=0 WHERE module='stock'");$queue->drain();
ani_check('accepted'===$wpdb->get_var($wpdb->prepare("SELECT state FROM {$store->table('stock_requests')} WHERE id=%d",$id))&&1===$calls,'live stock accepted only through mocked provider');
$p->set_stock_status('outofstock');$p->save();update_option('home','http://example.test');ani_rejects(fn()=>$service->request($p->get_id(),$user,true),'insecure live request rejected');
$p->delete(true);require_once ABSPATH.'wp-admin/includes/user.php';wp_delete_user($user);update_option('home',$home);update_option('ani_sms_modules',array('auth'));
echo 'Stock live boundary: '.$GLOBALS['ani_checks']." checks passed; HTTP mocked\n";
